-- ═══════════════════════════════════════════════════════════
-- 0097_food_recettes_fiches_14_11.sql
-- STATUT : PROPOSITION — à exécuter puis confirmer par Renée-Lise
-- Auteur : Claude Code · Date de rédaction : 2026-11-14
-- Objet : 16 fiches recettes (composition + étapes réelles) pour
--   Bella'Food, transcrites depuis les 14 images envoyées ce jour.
--   Table food_recettes uniquement (fiches internes), PAS de prix
--   conseillé renseigné → volontairement non synchronisé vers
--   catalogue_produits (notes n'entrant dans aucune clause des
--   migrations 0093/0095/0096).
--   Doublons retirés comme demandé :
--   - "Danette au chocolat maison" envoyée en 2 versions (une
--     courte "Chez Nounou Alex", une longue détaillée) → seule la
--     version longue est reprise.
--   - "Crème dessert aux spéculoos maison" envoyée deux fois à
--     l'identique (même image) → une seule entrée.
--   - La capture du menu Bella'Food existant (coffrets/prix) n'est
--     pas une recette → ignorée.
--   L'image "6 RECETTES DE DINDE" ne contenait que des listes
--   d'ingrédients par variante, sans étapes de préparation : les
--   6 variantes sont reprises comme 6 fiches distinctes (compositions
--   réellement différentes), avec une note explicite sur l'absence
--   d'étapes détaillées sur la fiche source.
-- Idempotent (WHERE NOT EXISTS sur nom + notes).
-- ═══════════════════════════════════════════════════════════

insert into public.food_recettes
  (nom, categorie, nb_parts, difficulte, temps_prepa, temps_cuisson, temps_repos, ingredients, etapes, notes, statut)
select v.nom, v.categorie, v.nb_parts, v.difficulte, v.temps_prepa, v.temps_cuisson, v.temps_repos, v.ingredients, v.etapes, v.notes, v.statut
from (values
('Crème dessert aux spéculoos maison', 'dessert', 4, 1, 15, null, 120, '[{"nom": "Lait entier", "quantite": 500, "unite": "ml"}, {"nom": "Sucre en poudre", "quantite": 40, "unite": "g"}, {"nom": "Maïzena", "quantite": 10, "unite": "g"}, {"nom": "Biscuits spéculoos", "quantite": 70, "unite": "g"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café", "notes": "facultatif"}, {"nom": "Crème liquide", "quantite": 10, "unite": "cl", "notes": "facultatif, pour une texture plus fondante"}]'::jsonb, ARRAY['Émiettez finement les spéculoos et réservez-en une petite quantité pour la décoration.','Dans un saladier, mélangez le sucre avec la Maïzena.','Versez progressivement le lait froid en fouettant pour éviter les grumeaux.','Faites chauffer le mélange à feu doux en remuant constamment jusqu''à ce qu''il épaississe.','Incorporez les spéculoos émiettés et la vanille, puis mélangez jusqu''à obtenir une crème lisse.','Ajoutez la crème liquide si désiré pour une texture encore plus fondante.','Répartissez dans des verrines, laissez refroidir puis placez au réfrigérateur pendant au moins 2 heures.','Parsemez de miettes de spéculoos juste avant de servir.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Bûche de Noël', 'patisserie', 8, 2, 30, 12, 120, '[{"nom": "Œufs", "quantite": 4, "unite": "piece", "notes": "pour le biscuit"}, {"nom": "Sucre", "quantite": 120, "unite": "g", "notes": "pour le biscuit"}, {"nom": "Farine", "quantite": 120, "unite": "g", "notes": "pour le biscuit"}, {"nom": "Sel", "quantite": 1, "unite": "pincée", "notes": "pour le biscuit"}, {"nom": "Chocolat noir pâtissier", "quantite": 200, "unite": "g", "notes": "pour la crème au chocolat"}, {"nom": "Crème liquide entière (30% MG)", "quantite": 500, "unite": "ml", "notes": "pour la crème au chocolat"}, {"nom": "Sucre glace", "quantite": 30, "unite": "g", "notes": "pour la crème au chocolat"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café", "notes": "facultatif, pour la crème au chocolat"}, {"nom": "Sucre glace", "unite": "g", "notes": "pour la décoration, quantité libre"}, {"nom": "Copeaux de chocolat ou vermicelles", "unite": "g", "notes": "pour la décoration, quantité libre"}, {"nom": "Petits sujets de Noël", "unite": "piece", "notes": "facultatif, pour la décoration"}]'::jsonb, ARRAY['Fouettez les œufs et le sucre pendant 5 minutes jusqu''à ce que le mélange blanchisse et double de volume.','Ajoutez délicatement la farine et la pincée de sel en mélangeant à la spatule.','Étalez la pâte sur une plaque recouverte de papier cuisson (environ 1 cm d''épaisseur).','Faites cuire 10 à 12 minutes à 180°C. Le biscuit doit rester souple. Laissez-le tiédir.','Démoulez sur un torchon humide et roulez-le délicatement. Laissez-le refroidir.','Faites fondre le chocolat. Montez la crème bien froide en chantilly, ajoutez le sucre glace puis incorporez le chocolat fondu. Mélangez délicatement.','Déroulez le biscuit et étalez une partie de la crème au chocolat. Roulez à nouveau.','Recouvrez toute la bûche de crème. Décorez avec des stries à l''aide d''une fourchette.','Ajoutez les décorations de Noël et placez au frais au moins 2 heures avant de déguster.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé. Astuce : parfumer la crème avec un peu de café, de praliné ou d''orange ; préparer la bûche la veille, elle sera encore meilleure.', 'actif'),
('Pâte à pizza classique', 'pizza', 2, 1, 20, 10, 120, '[{"nom": "Farine (type 00 ou T55)", "quantite": 280, "unite": "g"}, {"nom": "Sucre", "quantite": 1, "unite": "c. à café"}, {"nom": "Sel", "quantite": 1, "unite": "c. à café"}, {"nom": "Levure sèche de boulanger", "quantite": 1, "unite": "c. à café"}, {"nom": "Eau tiède (environ 35°C)", "quantite": 180, "unite": "ml"}, {"nom": "Huile d''olive", "quantite": 1, "unite": "c. à soupe"}]'::jsonb, ARRAY['Dans un grand saladier, versez la farine, le sucre, le sel et la levure sèche. Mélangez bien.','Faites un puits au centre de la farine.','Versez l''eau tiède dans le puits et ajoutez l''huile d''olive.','Mélangez avec une cuillère en bois jusqu''à ce que la pâte commence à se former.','Transférez la pâte sur le plan de travail légèrement fariné et pétrissez pendant 8 à 10 minutes jusqu''à obtenir une pâte lisse, souple et élastique.','Formez une boule, placez-la dans un saladier légèrement huilé. Couvrez d''un torchon propre et laissez lever 1h30 à 2h à température ambiante jusqu''à ce qu''elle double de volume.','Dégazez légèrement la pâte avec les poings, puis divisez-la en 2 boules égales (environ 280-300 g chacune).','Couvrez les boules d''un torchon et laissez reposer 15 à 30 minutes à température ambiante.','Étalez chaque boule au diamètre désiré sans appuyer sur les bords. Garnissez selon vos envies.','Préchauffez le four au maximum (250°C minimum) avec la plaque ou la pierre à pizza à l''intérieur. Enfournez la pizza 8 à 12 minutes, jusqu''à ce que la pâte soit dorée et croustillante et que la garniture soit bien cuite.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé. Pour 2 pizzas de 24-28 cm. Peut être préparée à l''avance et conservée au réfrigérateur jusqu''à 24h, ou congelée (boules bien emballées) jusqu''à 2 mois. Fermentation lente possible 12 à 24h au frais pour une pâte plus digeste.', 'actif'),
('Tartelette chocolat caramel', 'patisserie', 6, 2, 40, 15, 60, '[{"nom": "Farine", "quantite": 200, "unite": "g", "notes": "pour la pâte sablée cacao"}, {"nom": "Cacao en poudre", "quantite": 30, "unite": "g", "notes": "pour la pâte sablée cacao"}, {"nom": "Beurre froid", "quantite": 100, "unite": "g", "notes": "pour la pâte sablée cacao"}, {"nom": "Sucre glace", "quantite": 80, "unite": "g", "notes": "pour la pâte sablée cacao"}, {"nom": "Œuf", "quantite": 1, "unite": "piece", "notes": "pour la pâte sablée cacao"}, {"nom": "Chocolat noir", "quantite": 150, "unite": "g", "notes": "pour la ganache chocolat"}, {"nom": "Crème liquide", "quantite": 10, "unite": "cl", "notes": "pour la ganache chocolat"}, {"nom": "Caramel au beurre salé", "unite": "g", "notes": "garniture centrale, quantité à ajuster selon le nombre de tartelettes"}]'::jsonb, ARRAY['Préparez la pâte sablée cacao : sablez la farine, le cacao et le beurre froid, puis incorporez le sucre glace et l''œuf jusqu''à obtenir une pâte homogène. Réservez au frais 30 minutes.','Foncez les moules à tartelettes avec la pâte, piquez le fond et faites cuire à blanc (environ 15 minutes à 180°C). Laissez refroidir.','Garnissez le fond de chaque tartelette d''une couche de caramel au beurre salé.','Préparez la ganache : faites chauffer la crème liquide et versez-la sur le chocolat noir haché. Mélangez jusqu''à obtenir une ganache lisse et brillante.','Versez la ganache sur le caramel et laissez prendre au réfrigérateur au moins 1 heure avant de démouler et de servir.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Danette au chocolat maison', 'dessert', 5, 1, 15, null, 120, '[{"nom": "Lait entier", "quantite": 500, "unite": "ml"}, {"nom": "Maïzena", "quantite": 25, "unite": "g"}, {"nom": "Sucre", "quantite": 85, "unite": "g"}, {"nom": "Cacao en poudre non sucré", "quantite": 50, "unite": "g"}, {"nom": "Chocolat noir pâtissier (70%), haché", "quantite": 100, "unite": "g"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café"}, {"nom": "Sel", "quantite": 1, "unite": "pincée"}]'::jsonb, ARRAY['Mélangez la Maïzena, le cacao, le sucre et le sel dans une casserole, hors du feu.','Versez progressivement le lait froid en fouettant jusqu''à obtenir un mélange lisse.','Faites chauffer à feu moyen sans cesser de remuer jusqu''à épaississement, puis portez à ébullition.','Dès la première ébullition, retirez la casserole du feu. Ajoutez le chocolat noir et la vanille, puis mélangez jusqu''à ce que la préparation soit bien brillante.','Filtrez la préparation (pour éviter qu''il y ait trop de granulosité), répartissez-la dans des ramequins ou des verrines.','Laissez refroidir à température ambiante, recouvrez chaque crème d''un film plastique, puis placez au réfrigérateur pendant au moins 2 heures avant de déguster.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé. Astuce : pour une texture encore plus onctueuse, mélanger la Maïzena avec un peu de lait froid avant de l''ajouter au reste. Se conserve 3 à 4 jours au réfrigérateur. (Doublon fusionné : une version plus courte de la même recette, "Chez Nounou Alex", a aussi été envoyée — non reprise séparément comme demandé.)', 'actif'),
('Pain au beurre', 'pain', 8, 2, 35, 28, 90, '[{"nom": "Farine", "quantite": 500, "unite": "g"}, {"nom": "Levure boulangère sèche", "quantite": 7, "unite": "g"}, {"nom": "Lait tiède", "quantite": 20, "unite": "cl"}, {"nom": "Œufs", "quantite": 2, "unite": "piece"}, {"nom": "Beurre mou", "quantite": 80, "unite": "g"}, {"nom": "Sucre", "quantite": 30, "unite": "g"}, {"nom": "Sel", "quantite": 8, "unite": "g"}, {"nom": "Jaune d''œuf", "quantite": 1, "unite": "piece", "notes": "pour dorer"}]'::jsonb, ARRAY['Pétrissez la farine, la levure, le lait, les œufs, le sucre et le sel.','Incorporez le beurre et continuez à pétrir jusqu''à obtenir une pâte souple.','Laissez lever 1 heure.','Tressez la pâte, laissez lever 30 minutes supplémentaires.','Dorez au jaune d''œuf et enfournez 25 à 30 minutes à 180°C.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Accras de morue', 'street_food', 4, 1, 20, 4, null, '[{"nom": "Morue dessalée et cuite", "quantite": 250, "unite": "g"}, {"nom": "Farine", "quantite": 180, "unite": "g"}, {"nom": "Eau", "quantite": 15, "unite": "cl"}, {"nom": "Levure chimique", "quantite": 1, "unite": "c. à café"}, {"nom": "Cives", "quantite": 2, "unite": "piece"}, {"nom": "Gousses d''ail", "quantite": 2, "unite": "piece"}, {"nom": "Persil", "unite": "bouquet", "notes": "quantité au goût"}, {"nom": "Piment", "unite": "piece", "notes": "quantité au goût"}, {"nom": "Huile de friture", "unite": "l", "notes": "pour la friture"}]'::jsonb, ARRAY['Émiettez la morue et retirez les arêtes.','Mélangez la farine, la levure et l''eau.','Ajoutez la morue, les cives, l''ail, le persil et le piment hachés.','Déposez des cuillerées dans l''huile à 170°C.','Faites dorer 3 à 4 minutes et égouttez.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé.', 'actif'),
('Cinnamon rolls faciles ultra moelleux', 'patisserie', 9, 2, 30, 25, 120, '[{"nom": "Farine", "quantite": 500, "unite": "g", "notes": "pour la pâte"}, {"nom": "Lait tiède", "quantite": 250, "unite": "ml", "notes": "pour la pâte"}, {"nom": "Sucre", "quantite": 80, "unite": "g", "notes": "pour la pâte"}, {"nom": "Beurre fondu", "quantite": 75, "unite": "g", "notes": "pour la pâte"}, {"nom": "Œuf", "quantite": 1, "unite": "piece", "notes": "pour la pâte"}, {"nom": "Levure boulangère pour rolls (sachet)", "quantite": 1, "unite": "piece", "notes": "pour la pâte"}, {"nom": "Sel", "quantite": 1, "unite": "pincée", "notes": "pour la pâte"}, {"nom": "Beurre mou", "quantite": 100, "unite": "g", "notes": "pour la garniture"}, {"nom": "Sucre roux", "quantite": 150, "unite": "g", "notes": "pour la garniture"}, {"nom": "Cannelle", "quantite": 2, "unite": "c. à soupe", "notes": "pour la garniture"}, {"nom": "Cream cheese", "quantite": 150, "unite": "g", "notes": "pour le glaçage"}, {"nom": "Beurre mou", "quantite": 50, "unite": "g", "notes": "pour le glaçage"}, {"nom": "Sucre glace", "quantite": 100, "unite": "g", "notes": "pour le glaçage"}, {"nom": "Extrait de vanille", "quantite": 1, "unite": "c. à café", "notes": "pour le glaçage"}, {"nom": "Lait", "quantite": 1, "unite": "c. à soupe", "notes": "pour le glaçage, 1 à 2 c. à soupe selon la texture désirée"}]'::jsonb, ARRAY['Préparer la pâte : mélangez le lait tiède, la levure et le sucre. Ajoutez l''œuf, le beurre fondu, le sel et la farine. Pétrissez 8-10 min jusqu''à obtenir une pâte souple. Laissez lever 1h dans un endroit chaud.','Étaler et garnir : étalez la pâte en rectangle. Badigeonnez de beurre mou, saupoudrez de sucre roux et de cannelle.','Rouler et découper : roulez la pâte en boudin bien serré. Coupez en 8 à 10 morceaux.','Deuxième pousse : disposez les rolls dans un plat beurré. Laissez lever 45 min à 1h.','Cuisson : enfournez à 180°C pendant 20-25 min jusqu''à ce qu''ils soient bien dorés.','Préparer le glaçage : fouettez le cream cheese, le beurre, le sucre glace, la vanille et un peu de lait.','Garnir et déguster : nappez les cinnamon rolls tièdes avec le glaçage et savourez.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé. Astuces : utiliser du lait tiède (pas chaud) pour activer la levure ; ne pas trop fariner la pâte pour rester moelleux ; laisser bien lever. Variantes : caramel beurre salé, pépites de chocolat, noix de pécan, version automnale à la cannelle.', 'actif'),
('Pintade rôtie aux pommes', 'volaille', 5, 2, 25, 80, 10, '[{"nom": "Pintade entière", "quantite": 1, "unite": "piece", "notes": "1,5 à 1,8 kg"}, {"nom": "Pommes (Golden, Reine des reinettes ou Pink Lady)", "quantite": 4, "unite": "piece"}, {"nom": "Oignons jaunes", "quantite": 2, "unite": "piece"}, {"nom": "Gousses d''ail", "quantite": 3, "unite": "piece"}, {"nom": "Beurre", "quantite": 40, "unite": "g"}, {"nom": "Huile d''olive", "quantite": 2, "unite": "c. à soupe"}, {"nom": "Bouillon de volaille", "quantite": 20, "unite": "cl"}, {"nom": "Miel", "quantite": 2, "unite": "c. à soupe"}, {"nom": "Moutarde à l''ancienne", "quantite": 1, "unite": "c. à soupe"}, {"nom": "Thym frais", "quantite": 3, "unite": "branche"}, {"nom": "Romarin frais", "quantite": 2, "unite": "branche"}, {"nom": "Laurier", "quantite": 1, "unite": "feuille"}, {"nom": "Sel et poivre", "unite": "g", "notes": "au goût"}]'::jsonb, ARRAY['Préchauffez le four à 180°C. Sortez la pintade du réfrigérateur 20 minutes avant. Séchez-la, salez et poivrez l''intérieur et l''extérieur. Glissez à l''intérieur une branche de thym, une branche de romarin et une gousse d''ail légèrement écrasée.','Lavez les pommes, retirez les pépins et découpez-les en quartiers. Épluchez et coupez les oignons en quartiers. Écrasez légèrement 2 gousses d''ail. Réservez la moitié des pommes pour plus tard.','Mélangez le miel, la moutarde, l''huile d''olive, le sel et le poivre. Badigeonnez la pintade avec ce mélange. Déposez-la dans un plat, ajoutez les oignons, l''ail, la moitié des pommes, le beurre, le thym, le romarin et le laurier.','Enfournez 20 minutes à 180°C. Versez le bouillon de volaille dans le fond du plat, puis poursuivez la cuisson 55 minutes à 1h10. Arrosez régulièrement la viande avec son jus.','Environ 30 minutes avant la fin de la cuisson, ajoutez le reste des pommes. Laissez-les rôtir jusqu''à ce qu''elles soient tendres et légèrement caramélisées. Vérifiez la cuisson (74°C à cœur).','Laissez reposer la pintade 10 minutes sous une feuille d''aluminium. Découpez-la en morceaux, servez avec les pommes rôties et nappez de jus de cuisson. Ajoutez quelques brins de thym et de romarin pour la décoration.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé. Astuces : arroser régulièrement pour une viande moelleuse ; utiliser des pommes fermes ; ajouter marrons, pruneaux ou abricots secs pour une version festive ; servir avec un gratin dauphinois, une purée maison ou des légumes rôtis.', 'actif'),
('Saumon en croûte feuilletée', 'poisson', 6, 3, 30, 38, 5, '[{"nom": "Filet de saumon sans peau ni arêtes", "quantite": 1, "unite": "piece", "notes": "900 g à 1 kg"}, {"nom": "Épinards frais", "quantite": 300, "unite": "g"}, {"nom": "Fromage frais (type Philadelphia ou Saint-Môret)", "quantite": 150, "unite": "g"}, {"nom": "Échalote", "quantite": 1, "unite": "piece"}, {"nom": "Gousses d''ail", "quantite": 2, "unite": "piece"}, {"nom": "Beurre", "quantite": 20, "unite": "g"}, {"nom": "Huile d''olive", "quantite": 1, "unite": "c. à soupe"}, {"nom": "Citron jaune", "quantite": 1, "unite": "piece"}, {"nom": "Aneth frais", "quantite": 2, "unite": "c. à soupe"}, {"nom": "Moutarde douce", "quantite": 1, "unite": "c. à café", "notes": "facultatif"}, {"nom": "Sel et poivre", "unite": "g", "notes": "au goût"}, {"nom": "Pâtes feuilletées rectangulaires", "quantite": 2, "unite": "piece"}, {"nom": "Jaune d''œuf", "quantite": 1, "unite": "piece", "notes": "pour la dorure"}, {"nom": "Lait", "quantite": 1, "unite": "c. à soupe", "notes": "pour la dorure"}, {"nom": "Aneth frais, rondelles de citron, persil", "unite": "piece", "notes": "pour la décoration"}]'::jsonb, ARRAY['Préparer les épinards : faites revenir l''échalote et l''ail dans le beurre et l''huile d''olive. Ajoutez les épinards et laissez cuire 5 à 7 minutes jusqu''à évaporation de l''eau. Laissez refroidir et pressez pour retirer l''excédent d''humidité.','Préparer la garniture crémeuse : mélangez le fromage frais, l''aneth, le jus de citron et éventuellement la moutarde. Ajoutez les épinards refroidis. Salez, poivrez et réservez au frais.','Préparer le saumon : préchauffez le four à 200°C. Séchez le filet de saumon, assaisonnez-le avec du sel, du poivre et un peu de jus de citron.','Monter le saumon en croûte : étalez une pâte feuilletée, déposez une couche de garniture aux épinards, puis le saumon. Recouvrez avec le reste de la garniture et la deuxième pâte feuilletée. Soudez bien les bords.','Dorer et faire cuire : badigeonnez avec le jaune d''œuf et le lait. Dessinez des motifs sans percer la pâte. Enfournez 35 à 40 minutes à 200°C, jusqu''à ce que la pâte soit bien dorée. La température à cœur doit atteindre 63°C.','Découper et servir : laissez reposer 5 minutes avant de découper en tranches épaisses. Décorez avec de l''aneth et des rondelles de citron. Servez chaud avec une sauce citronnée, du riz ou des légumes rôtis.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé. Astuces : bien égoutter les épinards pour une pâte croustillante ; ajouter du saumon fumé pour une version festive ; remplacer une partie du fromage frais par du mascarpone ; varier avec des poireaux ; préparer la garniture la veille.', 'actif'),
('Dinde rôtie', 'volaille', 8, 2, 20, 180, null, '[{"nom": "Dinde entière", "unite": "kg", "notes": "4,5 à 5,5 kg"}, {"nom": "Huile d''olive", "unite": "tasse", "notes": "1/4 tasse"}, {"nom": "Beurre fondu", "unite": "tasse", "notes": "1/4 tasse"}, {"nom": "Sel", "unite": "c. à soupe", "notes": "1 1/2 c. à soupe"}, {"nom": "Poivre noir", "quantite": 1, "unite": "c. à café"}, {"nom": "Thym frais", "quantite": 2, "unite": "c. à soupe"}, {"nom": "Romarin frais", "quantite": 2, "unite": "c. à soupe"}, {"nom": "Sauge fraîche", "quantite": 2, "unite": "c. à soupe"}, {"nom": "Bouillon de poulet", "unite": "piece", "notes": "quantité non lisible sur la fiche"}, {"nom": "Oignon, en quartiers", "quantite": 1, "unite": "piece"}, {"nom": "Citron, coupé en deux", "quantite": 1, "unite": "piece"}, {"nom": "Gousses d''ail", "quantite": 4, "unite": "piece"}, {"nom": "Carottes, hachées", "quantite": 2, "unite": "piece"}, {"nom": "Branches de céleri, hachées", "quantite": 2, "unite": "piece"}]'::jsonb, ARRAY['Étapes non détaillées sur la fiche envoyée par Renée-Lise (infographie "6 recettes de dinde") — uniquement la liste des ingrédients par variante est fournie.','Principe général : assaisonner/mariner la dinde entière avec les ingrédients listés, puis rôtir au four jusqu''à cuisson à cœur — à préciser avec Renée-Lise pour les températures et temps exacts par variante.']::text[], 'Fiche recette envoyée par Renée-Lise le 14/11 — repère interne (composition/préparation), pas de prix de vente associé. Issue de l''infographie "6 recettes de dinde" envoyée en lot avec les autres fiches.', 'actif'),
